import {createFishPond} from './fish-state.js';
import {FISH} from './fish-config.js';import {fishPayment} from './fish-feed.js';import {fishReceipt} from './fish-stock.js';
/** No instant credit/oxygen grant: only subsequent purchased runtime changes. @param {import('./engine.js').State} state @param {import('./engine.js').Command} command @param {import('./fish-feed.js').FishTransaction} transact @returns {string|undefined} */
export function upgradeFishAir(state,command,transact){const g=state.fish,p=g?.ponds.find(x=>x.id===command.fishPond);if(!g||!p)return 'fishPondMissing';if(p.efficient)return 'fishUpgradeExists';if(g.stats.saleActions<1)return 'fishSellFirst';if(state.coins<FISH.efficiencyCoins)return 'noCoins';fishPayment(state,'fish.aerator_upgrade',-FISH.efficiencyCoins,'upgrade.'+p.id,transact);p.efficient=true;fishReceipt(g,state.tick,'efficiency',p.id,0,0,FISH.efficiencyCoins);}

/** Economic milestone uses actual grown fish and sales, never view visits or wallet alone. @param {import('./engine.js').State} state */
export function fishExpansionReason(state){const g=state.fish;if(!g?.visited)return 'fishNotVisited';if(g.ponds.length>=FISH.maxPonds)return 'fishPondLimit';if(!g.mission.completed.includes('first')||g.stats.growOutCount<4||g.stats.soldCount<8)return 'fishExpansionLocked';if(state.coins<FISH.pondCoins)return 'noCoins';return '';}
/** Price includes an empty basin with a basic OFF aerator, not another starter kit. @param {import('./engine.js').State} state @param {import('./engine.js').Command} command @param {import('./fish-feed.js').FishTransaction} transact @returns {string|undefined} */
export function expandFishPond(state,command,transact){if(command.fishPond!==1)return 'invalidFishCommand';const reason=fishExpansionReason(state);if(reason)return reason;const g=state.fish;if(!g)return 'fishNotVisited';fishPayment(state,'fish.pond_expansion',-FISH.pondCoins,'expand.2',transact);g.ponds.push(createFishPond(2,state.tick));fishReceipt(g,state.tick,'pond',2,0,0,FISH.pondCoins);}
